import{_ as r,l as i,o as e,c as s,v as t,p as l,x as n,d as E,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"前视偏差","description":"","frontmatter":{"title":"前视偏差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/look-ahead-bias.md","filePath":"quant/look-ahead-bias.md","lastUpdated":1789023840000}'),d={name:"quant/look-ahead-bias.md"};function A(c,a,m,B,u,_){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="前视偏差" tabindex="-1">前视偏差 <a class="header-anchor" href="#前视偏差" aria-label="Permalink to &quot;前视偏差&quot;">​</a></h1><div class="epigraph"><p>检验若使用了决策时点之后才到达的信息，拒绝无预测能力的概率不再是名义上的显著性，而是泄漏的函数。</p><footer>—— 对照 Lo and MacKinlay 对数据窥探与可预测性检验的警告</footer></div><p><a href="/quant/survivorship-bias">上一课</a>把「活到样本期末」筛选造成的业绩上偏钉住：时点宇宙与退市处理是同一套卫生。缺口是另一类不可实现：回测在 \\(t\\) 用了 \\(\\mathcal{F}_{t+h}\\) 里的信息。本课写前视偏差。不重讲 Shumway 的退市填充。后课点-in-time 基本面默认已经读完：信息集本身不合法，与<a href="/quant/overfit-as-risk">过拟合</a>（当时可得的数据仍把噪声搜成技能）不是同一病。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合法的回测要求：时刻 \\(t\\) 的权重 \\(w_t\\) 是映射 \\(f(\\mathcal{F}_t)\\)，而 \\(\\mathcal{F}_t\\) 只含当时公共可得的价格、已公布（且当时版本）的财务、当时的指数成份、当时的停牌状态。违约的典型路径包括：（1）用最新数据库的「最新报表」代替当时已发布数字，把事后更正提前；（2）用期末才知道的成份或行业分类；（3）用全样本均值方差、全样本主成分、全样本协整向量去生成每一天的仓位；（4）用未来实现波动或未来最高最低价做仓位或过滤。任何一条都会把样本内夏普往真实可交易水平之上推。</p><p>会计数字的时间线尤其容易错。财年结束于 12 月 31 日，并不等于 12 月 31 日收盘后就能交易账面价值。10-K 可能在 3 月才报出；中国年报在 4 月 30 日前。Fama 与 French 用 6 月作为统一可交易时点，是粗但可复制的 PIT 近似。若在 1 月就用当年年报的净资产排序，那是在用三个月后才存在的信息。</p><h3 id="静默的前视-标准化、排名与「已知的」公司行为" tabindex="-1">静默的前视：标准化、排名与「已知的」公司行为 <a class="header-anchor" href="#静默的前视-标准化、排名与「已知的」公司行为" aria-label="Permalink to &quot;静默的前视：标准化、排名与「已知的」公司行为&quot;">​</a></h3><p>对特征做横截面 z-score 时，若用当天全部股票的均值方差，一般可接受（收盘后调仓假设）。若用包含次日上市、次日才复牌的名字，或用未来窗口的分布做分位断点，则泄漏。更隐蔽的是拆股：研究里常用后复权价画图，把未来的拆股因子提前除到历史价格上——对收益计算若一致处理可以自洽，但对「价格小于 5 美元过滤」「整数值支撑」这类规则，复权价不是当时可交易价格。公司行为必须区分：当时已知的已宣布拆股，与回测软件默认的全历史调整因子。详见<a href="/quant/corporate-actions">分红、拆股与复权</a>。</p><p><span class="marginnote">用全样本估的对冲比 \\(\\beta\\) 去做每一天的配对，是最常见的学术前视。滚动或扩张窗口 \\(\\beta\\) 才与实时信息集相符。Johansen 向量若在全样本上估一次再回放残差，协整「看起来很稳」往往是因为 \\(\\beta\\) 已经看见了未来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>时间戳审计。</strong> 每个输入字段必须有 as-of 时间：价格用当时成交，财务用发布时点的版本，成份用当时名录，分析师用当时快照。Ljungqvist、Malloy 与 Marston（2009）发现 I/B/E/S 的历史推荐会被事后改写；没有 PIT 快照，分析师因子会含前视。工程检查：随机抽 \\(t\\)，把 \\(w_t\\) 的全部依赖列出来，问每个字段在 \\(t\\) 日收盘前是否可下载。</p><p><strong>滞后规则预指定。</strong> 账面、盈利、负债至少滞后到法定披露截止之后，或使用实际 file date。Asness–Frazzini 主张用最新已知账面、更频繁更新 HML，相对 FF 的年度 6 月滞后更激进，但仍明确拒绝未公布数字。争议应写成两种合法 PIT 规则的比较，而不是「用最新 Compustat 拉出来的数」。</p><p><strong>禁止全样本统计进仓位。</strong> 标准化、PCA、协方差、协整、HMM 平滑概率，一律用 \\(\\mathcal{F}_t\\)。平滑体制概率 \\(P(s_t\\mid\\mathcal{F}_T)\\) 只用于叙事，见<a href="/quant/regime-switching-premia">体制切换</a>。波动目标用已实现或预测波动的当时值，不用事后已知的当月实现。</p><h3 id="指数、停牌与成交假设" tabindex="-1">指数、停牌与成交假设 <a class="header-anchor" href="#指数、停牌与成交假设" aria-label="Permalink to &quot;指数、停牌与成交假设&quot;">​</a></h3><p>指数调入在宣布日与生效日之间有可交易的窗口；回测若在宣布前就把名字纳入「指数内策略」，是前视。停牌期间成交价不是可成交价，用线性插值填停牌日收益等于假装当时能交易，见<a href="/quant/trading-halts">停牌、涨跌停与不可交易</a>。VWAP 假设若用了当天全天成交量，对盘中策略是前视；收盘调仓策略用当日收盘价，在有涨跌停时仍可能买不到。</p><p><span class="marginnote">「研究用复权价、交易用未复权价」若分成两套代码且未对过滤规则对齐，会在低价股过滤上制造前视：未来拆股让历史复权价看起来从未低于 5 元，当时却低于 5 元。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前视改变的是策略作为可测函数的定义域。统计上，它让预测变量与未来残差相关，\\(t\\) 检验的原假设分布崩掉。经济上，它把不可交易的信息租金写进净值：更正后的盈利、事后才知道的退市、事后才稳定的行业分类，都不是当时能下单的信号。与幸存者的合谋尤其强：今天的成份既是生存筛选，也是对「谁将进入指数」的前视。</p><p>部分前视是连续的而不是开关。用 \\(t+1\\) 到 \\(t+5\\) 的数据做「更好的」当日波动估计，泄漏小于用整个样本，但仍然有偏。正确态度是把每一处未来窗口写成明确的滞后，并在敏感分析里拉长滞后，看 alpha 还剩多少。若 alpha 只存在于零滞后、在合法滞后下消失，它就不是可交易预测性。</p><h3 id="与数据窥探的关系" tabindex="-1">与数据窥探的关系 <a class="header-anchor" href="#与数据窥探的关系" aria-label="Permalink to &quot;与数据窥探的关系&quot;">​</a></h3><p>数据窥探（snooping）是在合法信息集上搜索过多；前视是信息集非法。可以同时发生：先用最新财务把因子做漂亮，再在参数网格上搜。纠正前视不会自动纠正过拟合，反之亦然。流程上应先冻结信息集（PIT），再在该信息集上限制搜索并计算紧缩夏普。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>真实发布时点数据贵、且有错误。用统一滞后（FF 的 6 月）是偏差与可行的折中，但必须承认：相对真 PIT，它可能过慢（丢掉及时信息）或偶尔仍过快（个别公司推迟披露）。无法获得 PIT 时，应把「最新可得」结果标成上界，而不是当成实盘预期。盘中微观结构研究还要处理交易所时间戳与迟到成交，那是另一层前视，见 tick 清洗一类工作。</p><p>不要用「我们只做月频，所以前视无所谓」：月频照样会在月初用当季尚未公布的季报。也不要在样本外一段「关掉」前视、样本内保留，那会让验证集看起来更差，从而诱使你改回泄漏版本。</p><p><span class="marginnote">复现别人因子时，对方若未声明滞后与数据库版本，你的无泄漏复制更弱，不一定说明对方造假，但说明对方数字不能当可交易 alpha 的上界。</span></p>',25)),(e(),l(p,null,{default:n(()=>[h(o,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%86%B3%E7%AD%96%E6%97%B6%E7%82%B9%20t%22%5D%20--%3E%20F%5B%22%E5%90%88%E6%B3%95%20F_t%22%5D%0A%20%20F%20--%3E%20W%5B%22%E6%9D%83%E9%87%8D%20w_t%22%5D%0A%20%20FUT%5B%22t%20%E4%B9%8B%E5%90%8E%E7%9A%84%E6%8A%A5%E8%A1%A8%E6%9B%B4%E6%AD%A3%20%2F%20%E6%88%90%E4%BB%BD%20%2F%20%E5%85%A8%E6%A0%B7%E6%9C%AC%E7%BB%9F%E8%AE%A1%22%5D%20--%3E%20BAD%5B%22%E9%9D%9E%E6%B3%95%E8%BE%93%E5%85%A5%22%5D%0A%20%20BAD%20--%3E%20W2%5B%22%E7%9C%8B%E8%B5%B7%E6%9D%A5%E6%9B%B4%E5%A5%BD%E7%9A%84%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20W2%20--%3E%20U%5B%22%E4%B8%8D%E5%8F%AF%E5%AE%9E%E7%8E%B0%E7%9A%84%E5%A4%8F%E6%99%AE%22%5D%0A%20%20AUDIT%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E5%AE%A1%E8%AE%A1%22%5D%20--%3E%20F%0A%20%20LAG%5B%22%E9%A2%84%E6%8C%87%E5%AE%9A%E6%BB%9E%E5%90%8E%22%5D%20--%3E%20F%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前视偏差是 \\(w_t\\) 依赖了当时不可得的信息；它使回测不可实现，而不只是使推断失真。</li><li>财务披露日历、指数成份、全样本估计的 \\(\\beta\\)/PCA、未来价格过滤，是主要泄漏源。</li><li>Fama–French 的 6 月滞后与 Asness–Frazzini 对 HML 时点的讨论，核心是 PIT 规则，不是要不要用账面。</li><li>先冻结信息集，再谈过拟合与多重检验；I/B/E/S 一类数据库存在事后改写，必须用快照。</li><li>出处：Lo and MacKinlay, <em>A Non-Random Walk Down Wall Street</em> 及相关数据窥探讨论；Fama and French 对 HML 构造中账面滞后的处理；Asness and Frazzini, <em>The Devil in HML’s Details</em>, Journal of Portfolio Management, 2013；Ljungqvist, Malloy and Marston, <em>Rewriting History</em>, Journal of Finance, 2009。</li></ul>',2))])}const q=r(d,[["render",A]]);export{F as __pageData,q as default};
